import { PasswordInput } from '@absoluteui/components/password-input';
import { PasswordStrengthMeter } from '@absoluteui/components/password-strength-meter';

const inputHost = document.querySelector<HTMLElement>('#password');
const meterHost = document.querySelector<HTMLElement>('#meter');
if (inputHost && meterHost) {
  const password = PasswordInput.create(inputHost, { label: 'New password', autocomplete: 'new-password' });
  const meter = PasswordStrengthMeter.create(meterHost, { input: password });
  password.update({ describedBy: [meter.describedById] });
}

import { PasswordInput } from '@absoluteui/components/password-input';
import { PasswordStrengthMeter, passwordRequirements, type PasswordStrengthEvaluator } from '@absoluteui/components/password-strength-meter';

const evaluate: PasswordStrengthEvaluator = (value, requirements) => {
  const met = requirements.filter((r) => r.met).length;
  if (value === '') return { score: 0 };
  return { score: met === requirements.length ? (value.length >= 20 ? 4 : 3) : 1 };
};

const inputHost = document.createElement('div');
const meterHost = document.createElement('div');
document.body.append(inputHost, meterHost);
const password = PasswordInput.create(inputHost, { label: 'New password', autocomplete: 'new-password' });
const meter = PasswordStrengthMeter.create(meterHost, {
  input: password,
  requirements: [
    passwordRequirements.minLength(14),
    passwordRequirements.symbol(),
    { id: 'no-company', label: 'Does not contain the company name', test: (v) => !v.toLowerCase().includes('acme') },
  ],
  evaluate,
});
password.update({ describedBy: [meter.describedById] });
